<?php
require_once 'includes/auth.php';
if($_SERVER['REQUEST_METHOD']==='POST'){admin_check_csrf();$id=(int)$_POST['id'];$status=$_POST['status'];$allowed=['pending','approved','paid','shipped','delivered','cancelled'];if(in_array($status,$allowed,true)){$s=$pdo->prepare('UPDATE orders SET status=? WHERE id=?');$s->execute([$status,$id]);}}$orders=$pdo->query("SELECT o.*,COALESCE(o.guest_name,u.name,'Guest') customer,COALESCE(o.guest_email,u.email) email FROM orders o LEFT JOIN users u ON u.id=o.user_id ORDER BY o.id DESC")->fetchAll();
$page_title='Orders';
require 'includes/header.php';
?><div class="table-wrap"><table class="table"><tr><th>Order</th><th>Customer</th><th>Phone</th><th>Address</th><th>Total</th><th>Status</th><th>Date</th><th>Save</th></tr><?php foreach($orders as $o):?><tr><td>#<?=intval($o['id'])?></td><td><?=admin_h($o['customer'])?><br><span class="muted"><?=admin_h($o['email']??'')?></span></td><td><?=admin_h($o['guest_phone']??'')?></td><td><?=admin_h($o['address']??'')?></td><td><?=CURRENCY.number_format($o['total'],2)?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=admin_csrf()?>"><input type="hidden" name="id" value="<?=intval($o['id'])?>"><select name="status"><?php foreach(['pending','approved','paid','shipped','delivered','cancelled'] as $st):?><option <?=($o['status']===$st?'selected':'')?> value="<?=$st?>"><?=$st?></option><?php endforeach;?></select></td><td><?=admin_h($o['created_at'])?></td><td><button class="btn">Update</button></form> <a class="btn gray" href="order_view.php?id=<?=intval($o['id'])?>">View</a></td></tr><?php endforeach;?></table></div><?php require 'includes/footer.php';
